<?php
$n = (int)trim(fgets(STDIN));

// We simulate the process using a stack
// Each element in the stack represents a slime value
$stack = [];

for ($i = 0; $i < $n; $i++) {
    // Add a new slime with value 1
    $stack[] = 1;

    // While the last two slimes have the same value, combine them
    while (count($stack) >= 2) {
        $last = $stack[count($stack) - 1];
        $secondLast = $stack[count($stack) - 2];
        if ($last === $secondLast) {
            // Remove the last two
            array_pop($stack);
            array_pop($stack);
            // Add the combined slime
            $stack[] = $last + 1;
        } else {
            break;
        }
    }
}

// Output the final state
echo implode(' ', $stack) . "\n";
?>
